from pathlib import Path
p=Path('src/App.tsx');s=p.read_text(encoding='utf-8-sig');s=s.replace("[query,setQuery]=useState('')","[query,setQuery]=useState(''),[deliveryType,setDeliveryType]=useState('СЦ'),[boxCount,setBoxCount]=useState('1')")
