s=s[:a]+'''{tab==='assembly'&&assembly.length>0&&assembly.every(i=>orderStatus(i)==='ready')&&<div className="delivery-controls"><fieldset className="delivery-options" aria-label="Способ передачи"><label><input type="radio" name="delivery-type" value="СЦ" checked={deliveryType==='СЦ'} onChange={()=>setDeliveryType('СЦ')}/>В СЦ</label><label><input type="radio" name="delivery-type" value="ПВЗ" checked={deliveryType==='ПВЗ'} onChange={()=>setDeliveryType('ПВЗ')}/>В ПВЗ</label></fieldset>{deliveryType==='ПВЗ'&&<div className="box-count"><FieldLabel htmlFor="delivery-boxes">Коробов</FieldLabel><Input id="delivery-boxes" type="number" min="1" step="1" inputMode="numeric" value={boxCount} onChange={e=>setBoxCount(e.target.value)}/></div>}<Button disabled={deliveryType==='ПВЗ'&&(!/^\\d+$/.test(boxCount)||!Number.isSafeInteger(Number(boxCount))||Number(boxCount)<1)} onClick={()=>{if(!assembly.every(i=>orderStatus(i)==='ready'))return;if(deliveryType==='ПВЗ'&&(!/^\\d+$/.test(boxCount)||!Number.isSafeInteger(Number(boxCount))||Number(boxCount)<1))return;setItems(prev=>prev.map(i=>assembly.some(a=>a.id===i.id)?{...i,phase:'shipped',stock:Math.max(0,i.stock-1),deliveryType,boxCount:deliveryType==='ПВЗ'?Number(boxCount):undefined}:i));toast.success(`Поставка передана в ${deliveryType}${deliveryType==='ПВЗ'?` · Коробов: ${boxCount}`:''}`)}}><Truck data-icon="inline-start"/>Передать в доставку</Button></div>}'''+s[b:]
